svg.script:
(function () {
  var svg = document.getElementById('backpack-svg') || document.documentElement;
  var isOpen = false;
  var isAnimating = false;
  var ANIM_MS = 1550;
  var rewardIds = ['reward-free-delivery', 'reward-5', 'reward-7', 'reward-10', 'reward-30', 'reward-50'];
  var storageKey = 'threads-t03-backpack-reward-v1';
  var selectedReward = null;
  var thresholds = [0.5, 0.8, 0.92, 0.989, 0.999, 1];
  // QA-only SVG URL parameter. Does not read or write the real visitor reward.
  var reviewReward = null;
  try {
    var requested = new URLSearchParams(window.location.search).get('threads-review-reward');
    if (rewardIds.indexOf(requested) !== -1) reviewReward = requested;
  } catch (error) {}
  function readSavedReward() {
    try {
      var saved = localStorage.getItem(storageKey);
      if (rewardIds.indexOf(saved) !== -1) return saved;
      // Migrate legacy reward values without rerolling.
      var legacy = localStorage.getItem('threads-t03-reward') || localStorage.getItem('threads-backpack-reward');
      if (legacy && rewardIds.indexOf(legacy) !== -1) {
        localStorage.setItem(storageKey, legacy);
        return legacy;
      }
    } catch (error) { /* Private storage restrictions: preserve in-memory choice. */ }
    return null;
  }
  function pickWeightedReward(randomValue) {
    for (var i = 0; i < thresholds.length; i++) {
      if (randomValue < thresholds[i]) return rewardIds[i];
    }
    return rewardIds[rewardIds.length - 1];
  }
  function showReward(id) {
    for (var i = 0; i < rewardIds.length; i++) {
      var el = document.getElementById(rewardIds[i]);
      if (el) el.setAttribute('display', rewardIds[i] === id ? 'inline' : 'none');
    }
  }
  selectedReward = reviewReward || readSavedReward();
  if (selectedReward) showReward(selectedReward);
  else showReward(null);
  function revealReward() {
    if (!selectedReward) {
      selectedReward = pickWeightedReward(Math.random());
      try { localStorage.setItem(storageKey, selectedReward); } catch (error) {}
    }
    showReward(selectedReward);
  }

  function toggleBackpack(evt) {
    if (evt && evt.type === 'keydown' && evt.key !== 'Enter' && evt.key !== ' ') {
      return;
    }
    if (evt && evt.type === 'keydown') {
      evt.preventDefault();
    }
    if (isAnimating) {
      return;
    }
    isAnimating = true;

    if (!isOpen) {
      revealReward();
      svg.classList.remove('is-closed', 'is-closing');
      svg.classList.add('is-opening');
      isOpen = true;
    } else {
      svg.classList.remove('is-opening');
      svg.classList.add('is-closing');
      isOpen = false;
    }

    setTimeout(function () {
      isAnimating = false;
    }, ANIM_MS);
  }

  svg.addEventListener('click', toggleBackpack, false);
  svg.addEventListener('keydown', toggleBackpack, false);
})();
